import java.lang.reflect.*;

interface Order { String place(int id); }
class OrderImpl implements Order {
    public String place(int id) {
        if (id <= 0) throw new IllegalArgumentException("bad id");
        return "ok:" + id;
    }
}
class AdvisedHandler implements InvocationHandler {
    private Object target;
    AdvisedHandler(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        Object r = null; boolean ok = true;
        try {
            r = m.invoke(target, args);
            return r;
        } catch (InvocationTargetException e) {
            ok = false;
            Throwable c = e.getCause();
            System.out.println("[afterThrowing] " + c.getMessage());
            throw c;
        } finally {
            if (ok) System.out.println("[afterReturning] " + m.getName() + " -> " + r);
            else System.out.println("[after] " + m.getName() + " finished with exception");
        }
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        Order proxy = (Order) Proxy.newProxyInstance(Order.class.getClassLoader(),
            new Class[]{Order.class}, new AdvisedHandler(new OrderImpl()));
        System.out.println(proxy.place(10));
        try { proxy.place(0); } catch (Exception e) {
            System.out.println("caught: " + e.getMessage());
        }
    }
}
